<script>
  import {onMount} from 'svelte';
  import {encryptBallot,verifyBoard} from './ballot.js';
  import * as Attest from '../scripts/attest/client.mjs';
  import {readPage,pageHref} from '../scripts/page-routes.mjs';
  import {signRequest} from '../scripts/auth-sign.mjs';
  Attest.configure({server:'https://attest.monster'});
  const {page,topicId}=readPage(location.pathname);
  const hrefFor=next=>pageHref(next,topicId);
  const apiBase=topicId?'/api/topics/'+encodeURIComponent(topicId):'/api';
  const checkpointKey='vote-anyway-checkpoint:'+(topicId||'neighborhood-demo-2026');
  let step=$state('choose'),choice=$state(''),receipt=$state(null),busy=$state(false),error=$state('');
  let pendingBallot=null;
  let identity=$state(null),topics=$state([]),topicTitle=$state(''),topicQuestion=$state(''),topicChoices=$state('Yes\nNo'),createdTopic=$state(null),agentRequest=$state(null),myAgents=$state([]),grantScopes=$state([]);
  let isSignedIn=$derived(!!identity);
  let config=$state(null),configured=$state(false),lookup=$state(new URLSearchParams(location.search).get('receipt')||''),lookupResult=$state(''),auditResult=$state(''),totals=$state(null),savedCheckpoint=$state(null);
  let options=$derived(config?.election?.options??[]);
  onMount(async()=>{
    try{const draft=JSON.parse(sessionStorage.getItem('vote-anyway-return')||'null');if(draft){topicTitle=draft.title;topicQuestion=draft.question;topicChoices=draft.choices;choice=draft.choice;sessionStorage.removeItem('vote-anyway-return');}}catch{}
    try{config=await api(apiBase+'/config');configured=config.mode==='encrypted-lab';try{savedCheckpoint=JSON.parse(localStorage.getItem(checkpointKey)||'null');}catch{}}catch{configured=false;}
    if(Attest.session()){try{identity=await api('/api/session',{},true);}catch(e){Attest.clearSession();error=e.message;}}
    if(page==='agents')await loadAgents();
    if(page==='topics')await loadTopics();
    if(page==='board'&&configured)await audit();
  });
  async function api(url,init={},signed=false){
    const method=init.method||'GET';
    if(signed||method==='POST'){
      const session=Attest.session();if(!session)throw Error('Sign in with attest.monster to continue.');
      const device=await Attest.deviceKey();
      const authorization=await signRequest({id:session.id,origin:location.origin,jwk:device.jwk,privateKey:device.privateKey,method,path:url,body:init.body?JSON.parse(init.body):null});
      init={...init,headers:{...init.headers,authorization}};
    }
    const response=await fetch(url,init);const body=await response.json();
    if(!response.ok){if(response.status===401){identity=null;Attest.clearSession();}throw Object.assign(Error(body.error||'Service unavailable. Please try again.'),{status:response.status});}return body;
  }
  async function signIn(){error='';try{sessionStorage.setItem('vote-anyway-return',JSON.stringify({page,title:topicTitle,question:topicQuestion,choices:topicChoices,choice}));await Attest.signIn({mode:'redirect'});}catch(e){error=e.message;}}
  function signOut(){Attest.clearSession();identity=null;}
  async function loadTopics(){busy=true;try{topics=(await api('/api/topics')).topics;}catch(e){error=e.message;}finally{busy=false;}}
  async function createTopic(){busy=true;error='';try{createdTopic=await api('/api/topics',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:topicTitle,question:topicQuestion,options:topicChoices.split('\n').map(s=>s.trim()).filter(Boolean)})});}catch(e){error=e.message;}finally{busy=false;}}
  async function loadAgents(){error='';try{const id=new URLSearchParams(location.search).get('request');if(id){agentRequest=await api('/api/agent-requests/'+encodeURIComponent(id));grantScopes=[...agentRequest.scopes];}if(identity)myAgents=(await api('/api/agents',{},true)).agents;}catch(e){error=e.message;}}
  async function approveAgent(){busy=true;error='';try{agentRequest=await api('/api/agent-requests/'+agentRequest.id+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scopes:grantScopes})});await loadAgents();}catch(e){error=e.message;}finally{busy=false;}}
  async function revokeAgent(id){busy=true;error='';try{await api('/api/agents/'+id+'/revoke',{method:'POST'});await loadAgents();}catch(e){error=e.message;}finally{busy=false;}}
  function saveCheckpoint(value){savedCheckpoint=value;try{localStorage.setItem(checkpointKey,JSON.stringify(value));}catch{}}
  async function cast(){
    busy=true;error='';
    try{
      if(!pendingBallot||pendingBallot.choice!==choice)pendingBallot={choice,...await encryptBallot(config,choice)};
      const encrypted=pendingBallot;
      let record;
      try{record=await api(apiBase+'/vote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ciphertext:encrypted.ciphertext})});}
      catch(e){
        if(e.status!==409)throw e;
        const found=await api(apiBase+'/receipt?receipt='+encrypted.receipt);
        if(!found.found)throw e;
        const board=await api(apiBase+'/board');const row=board.records.find(r=>r.receipt===encrypted.receipt);
        if(!row)throw e;
        record={receipt:encrypted.receipt,index:row.index,head:row.hash,checkpoint:{electionId:config.election.id,count:row.index,head:row.hash,signingPublicKey:config.signingPublicKey}};
      }
      if(record.receipt!==encrypted.receipt)throw Error('The returned receipt does not match the encrypted ballot.');
      receipt=record;step='receipt';
      // Verify continuity before replacing the previously observed checkpoint.
      const board=await api(apiBase+'/board');
      const check=await verifyBoard(board,config.signingPublicKey,config.election.id,savedCheckpoint,record.receipt);
      saveCheckpoint(check);
    }catch(e){error=(e.message||'Could not confirm the ballot.')+(step==='receipt'?' Your submission was recorded, but verification did not complete. Keep your receipt.':' If the connection failed, retrying this submission uses the same encrypted ballot.');}finally{busy=false;}
  }
  async function verify(){
    lookupResult='';error='';busy=true;
    try{
      const hash=lookup.trim().toLowerCase();
      if(!/^[a-f0-9]{64}$/.test(hash))throw Error('Enter the full 64-character receipt code.');
      const found=await api(apiBase+'/receipt?receipt='+hash);
      if(found.found){const board=await api(apiBase+'/board');const prior=!!savedCheckpoint;const check=await verifyBoard(board,config.signingPublicKey,config.election.id,savedCheckpoint,hash);saveCheckpoint(check);lookupResult='Included at record '+found.index+'. Signatures and record chain checked in your browser.'+(prior?' Consistent with your saved checkpoint.':' First observation: save a checkpoint to compare future records.');}
      else{if(topicId)throw Error('Receipt not found in this topic.');const legacy=await api('/api/receipts/'+hash);lookupResult='Found in the earlier practice receipt register ('+new Date(legacy.createdAt).toLocaleDateString()+'). This fingerprint is not an encrypted ballot.';}
    }catch(e){error=e.message;}finally{busy=false;}
  }
  function download(value,name){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
  async function audit(){busy=true;error='';auditResult='';try{const board=await api(apiBase+'/board');const prior=!!savedCheckpoint;const check=await verifyBoard(board,config.signingPublicKey,config.election.id,savedCheckpoint);saveCheckpoint(check);auditResult=check.count+' signed records checked in your browser.'+(prior?' Consistent with your saved checkpoint.':' First observation: checkpoint saved in this browser.');totals=await api(apiBase+'/results');}catch(e){error=e.message;}finally{busy=false;}}
</script>

<svelte:head><title>Vote Anyway — {page==='home'?'Democracy, more often.':page==='ballot'?'Practice ballot':page==='verify'?'Check a receipt':page==='board'?'Public record':page==='create'?'Start a vote':page==='topics'?'Open topics':page==='agents'?'Your agents':'Where we are'}</title></svelte:head>
<div class="notice">AN OPEN EXPERIMENT IN DEMOCRACY <span>Independent. Unofficial. In progress.</span></div>
<header>
  <a class="brand" href="/" aria-label="Vote Anyway home"><span class="mark">v<span>↗</span></span>vote anyway<span class="brand-dot">.</span></a>
  <nav aria-label="Main navigation"><a href="/topics" class:active={page==='topics'}>Topics</a><a href="/devlog.html">Devlog</a><a href="/essay.html">Read the essay</a><a href="/about" class:active={page==='about'}>Where we are</a><a href="/research.html">Research &amp; sources</a><a href={hrefFor('verify')} class:active={page==='verify'}>Check a receipt</a><a href={hrefFor('board')} class:active={page==='board'}>Public record</a><a href="https://github.com/anselm/vote-anyway" target="_blank" rel="noreferrer">GitHub ↗</a><a href="/agents.html">For agents</a>{#if identity}<a href="/account/agents">Your agents</a><button onclick={signOut}>Sign out · @{identity.handle}</button>{:else}<button onclick={signIn}>Sign in</button>{/if}</nav>
</header>
<main>
{#if page==='home'}
  <section class="hero">
    <div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> A WORKING IDEA, OPEN TO EVERYONE</div><h1>Democracy,<br/>more <em>often.</em></h1><p class="intro">What if having a say were as simple as sending a message?</p><p class="muted hero-description">Vote Anyway is an experiment in making collective decisions more accessible, more frequent, and open to inspection. An essay and a working prototype, growing together.</p><div class="actions"><a class="primary" href="/topics/new">Start a vote <span>↗</span></a><a class="text-link" href="/ballot">Try the example ballot</a><a class="text-link" href="/about">Explore the idea ↗</a></div><p class="fine">Sign in with attest.monster to participate. Entirely unofficial.</p></div>
    <figure class="hero-photo"><img src="/images/voting-line-anchorage.png" width="1440" height="959" alt="People waiting in a long line beside a polling-place sign at Anchorage’s Midtown Mall."/><figcaption>Early voting, Anchorage’s Midtown Mall · October 19, 2026.<br/><a href="https://www.adn.com/politics/2026/10/19/show-up-and-do-your-part-early-voting-begins-in-alaska-with-long-lines-in-anchorage/" target="_blank" rel="noreferrer">Photo: Bill Roth / Anchorage Daily News</a></figcaption></figure>
  </section>
  <section class="principles"><article><span class="number">01</span><h2>A say, more often.</h2><p>Explore what changes when participation fits into everyday life.</p></article><article><span class="number">02</span><h2>Trust you can inspect.</h2><p>Build toward decisions whose records can be checked independently.</p></article><article><span class="number">03</span><h2>Ideas put into practice.</h2><p>Let working experiments inform the argument—and the next experiment.</p></article></section>
  <section class="lower"><div><div class="eyebrow">THE FIRST STEP</div><h2>Start small.<br/>Ask bigger questions.</h2></div><div><p>Try a fictional neighborhood ballot, check its receipt, and inspect the public record. The essay and its appendices explore the larger possibilities.</p><p class="muted">Explore browser-encrypted ballots, signed public records, and receipt verification. Eligibility and independently verifiable tallying remain research questions.</p><a class="text-link" href="/about#where-we-are">See what’s built and what’s next ↗</a> · <a class="text-link" href="/research.html">Read the research &amp; sources ↗</a></div></section>
{:else if page==='ballot'}
  <section class="workspace"><a class="back" href="/">← Back to the experiment</a><div class="eyebrow">{topicId?'AN OPEN TOPIC':'EXAMPLE BALLOT'}</div><h1 class="page-title">{config?.election?.title??'A little more collective possibility.'}</h1><p class="intro">{config?.election?.description??'Fictional neighborhood improvement exercise'}</p><p class="muted">EXPERIMENTAL VOTE — NOT AN OFFICIAL ELECTION. Participating here does not cast or change your real ballot.</p>
  {#if !identity}<div class="panel"><p>Sign in with attest.monster to submit a vote.</p><button class="primary" onclick={signIn}>Sign in with attest.monster ↗</button></div>{/if}<p class="fine">Share this topic: <a href={location.origin+hrefFor('ballot')}>{location.origin+hrefFor('ballot')}</a></p><div class="step-line"><span class:current={step==='choose'}>01 Choose</span><span class:current={step==='review'}>02 Review</span><span class:current={step==='receipt'}>03 Receipt</span></div>
  {#if step==='choose'}<fieldset><legend>Choose one option</legend>{#each options as option}<label class="option" class:selected={choice===option.id}><input type="radio" name="choice" value={option.id} bind:group={choice}/><div><strong>{option.label}</strong></div></label>{/each}</fieldset><button class="primary" disabled={!choice||!configured||!isSignedIn} onclick={()=>step='review'}>Review my choice <span>→</span></button>
  {:else if step==='review'}<div class="panel"><div class="eyebrow">YOUR PRACTICE CHOICE</div><h2>{options.find(o=>o.id===choice)?.label}</h2><p>Your browser encrypts this fictional ballot before sending it. The server checks the selection, stores the ciphertext, and adds a signed record to the public log.</p><p class="fine">The operator can decrypt ballots and computes the demonstration totals. Repeat participation is allowed. This experiment does not establish voter eligibility or independently prove the tally.</p></div><div class="actions"><button class="primary" disabled={busy||!configured||!isSignedIn} onclick={cast}>{busy?'Encrypting and submitting…':'Submit experimental ballot'} <span>↗</span></button><button class="text-link" disabled={busy} onclick={()=>step='choose'}>Change choice</button></div>
  {:else}<div class="panel receipt"><span class="success-icon">✓</span><div class="eyebrow">PRACTICE COMPLETE</div><h2>Your voice starts somewhere.</h2><p>Your encrypted ballot is recorded in the public log at position {receipt.index}.</p><label for="receipt-code">Your receipt code</label><code id="receipt-code">{receipt.receipt}</code><p class="fine">EXPERIMENTAL VOTE — NOT AN OFFICIAL ELECTION. Participating here does not cast or change your real ballot. Keep your receipt and checkpoint to check the record later.</p><div class="actions"><a class="primary" href={hrefFor('verify')+'?receipt='+receipt.receipt}>Check this receipt →</a><button class="text-link" onclick={()=>download(receipt,'vote-anyway-receipt.json')}>Download receipt ↓</button></div></div>{/if}
  {#if error}<p class="error" role="alert">{error}</p>{/if}<p class="storage-note">{configured?'Encrypted-ballot experiment connected.':'The voting experiment is unavailable. Please try again shortly.'}</p></section>
{:else if page==='verify'}
  <section class="workspace"><a class="back" href="/">← Home</a><div class="eyebrow">FOLLOW THE RECORD</div><h1 class="page-title">A receipt.<br/><em>A place to begin.</em></h1><p class="intro">Check a practice receipt.</p>{#if topicId&&config}<p class="fine">Topic: <a href={hrefFor('ballot')}>{config.election.title}</a></p>{/if}<p class="muted">Paste your receipt code. Your browser checks the signed public log and compares it with any checkpoint saved on this device.</p><form class="panel" onsubmit={(event)=>{event.preventDefault();verify();}}><label for="lookup">Receipt code</label><input id="lookup" class="code-input" bind:value={lookup} placeholder="Enter your 64-character receipt code" autocomplete="off" spellcheck="false" required/><button class="primary" disabled={busy}>{busy?'Checking…':'Find my receipt'} <span>→</span></button>{#if lookupResult}<p class="result" role="status">✓ {lookupResult}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</form><p class="fine">This checks signed record integrity and inclusion. It does not verify voter eligibility, ballot intent, or the server’s tally. The signing key is obtained from this site; independent checking requires an authentic key and a trusted earlier checkpoint.</p></section>
{:else if page==='topics'}
  <section class="workspace"><div class="eyebrow">QUESTIONS WE CAN ASK TOGETHER</div><h1 class="page-title">Open topics.</h1><p>Choose a question, participate, and inspect the record. These are informal, self-selected votes.</p><a class="primary inline" href="/topics/new">Start a vote ↗</a>{#if busy}<p>Loading topics…</p>{/if}{#each topics as topic}<article class="panel"><h2><a href={'/topic/'+topic.id}>{topic.title}</a></h2><p>{topic.question}</p><p class="fine">{topic.submissions} submissions</p></article>{/each}{#if error}<p class="error" role="alert">{error}</p>{/if}</section>
{:else if page==='create'}
  <section class="workspace"><a class="back" href="/topics">← Topics</a><div class="eyebrow">MAKE ROOM FOR A QUESTION</div><h1 class="page-title">Start a vote.</h1><p class="intro">Give a topic a question, a few choices, and a place to begin.</p>{#if createdTopic}<div class="panel"><h2>Your topic is open.</h2><p>Share this link so people can sign in and participate:</p><a class="share-link" href={createdTopic.url}>{location.origin+createdTopic.url}</a><p><a class="primary inline" href={createdTopic.url}>Open the ballot →</a></p></div>{:else}{#if !identity}<div class="panel"><p>Sign in with attest.monster to create a topic.</p><button class="primary" onclick={signIn}>Sign in with attest.monster ↗</button></div>{/if}<form class="panel topic-form" onsubmit={event=>{event.preventDefault();createTopic();}}><label for="topic-title">Topic title</label><input id="topic-title" bind:value={topicTitle} maxlength="120" required placeholder="A neighborhood idea"/><label for="topic-question">Question</label><textarea id="topic-question" bind:value={topicQuestion} maxlength="500" rows="3" required placeholder="What should we explore together?"></textarea><label for="topic-choices">Choices — one per line</label><textarea id="topic-choices" bind:value={topicChoices} rows="5" required></textarea><p class="fine">Use 2–8 distinct choices, up to 120 characters each. The question and choices are fixed once published. Signed-in participants can submit more than once; these totals are not a representative poll or an official election.</p><button class="primary" disabled={busy||!identity}>{busy?'Publishing…':'Publish topic'} ↗</button></form>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</section>
{:else if page==='agents'}
  <section class="workspace"><h1 class="page-title">Your agents.</h1><p>Give an agent specific permissions to act through Vote Anyway. You can take them back here.</p>{#if !identity}<button class="primary" onclick={signIn}>Sign in with attest.monster ↗</button>{/if}{#if agentRequest}<div class="panel"><h2>{agentRequest.name}</h2><p>{agentRequest.purpose}</p><p>Status: {agentRequest.status}</p>{#if agentRequest.status==='pending'}<fieldset><legend>Allow this agent to:</legend>{#each agentRequest.scopes as scope}<label class="option"><input type="checkbox" bind:group={grantScopes} value={scope}/>{scope==='topics:create'?'Create topics':'Submit votes'}</label>{/each}</fieldset><p class="fine">Access lasts up to seven days, or until your attest sign-in expires or is revoked. Approve only if you initiated this request and recognize the agent. Permission to submit votes allows repeat submissions.</p><button class="primary" disabled={busy||!identity||!grantScopes.length} onclick={approveAgent}>Approve selected permissions</button>{:else if agentRequest.status==='approved'}<p class="result">Approved. The agent can now continue.</p>{/if}</div>{/if}{#each myAgents as grant}<article class="panel"><h2>{grant.name}</h2><p>{grant.scopes.join(', ')} · Expires {new Date(grant.expiresAt).toLocaleString()}</p>{#if grant.revokedAt}<p>Revoked</p>{:else}<button disabled={busy} onclick={()=>revokeAgent(grant.id)}>Revoke access</button>{/if}</article>{/each}<p><a href="/agents.html">Agent guide and API documentation</a></p>{#if error}<p class="error" role="alert">{error}</p>{/if}</section>
{:else if page==='board'}
  <section class="workspace"><a class="back" href="/">← Home</a><div class="eyebrow">OPEN TO INSPECTION</div><h1 class="page-title">The public<br/><em>record.</em></h1><p class="intro">Signed records, open questions.</p>{#if topicId&&config}<p class="fine">Topic: <a href={hrefFor('ballot')}>{config.election.title}</a></p>{/if}<p>Check the encrypted records in your browser, download them, or use the independent checker. A saved checkpoint lets you detect a shorter or conflicting history later.</p><div class="actions"><button class="primary" disabled={busy||!configured} onclick={audit}>{busy?'Checking…':'Verify public record'}</button><a class="text-link" href={apiBase+'/board'} download="board.json">Download log ↓</a><a class="text-link" href={apiBase+'/signing-key.pem'} download="signing-public-key.pem">Public key ↓</a></div>
  {#if auditResult}<p class="result" role="status">{auditResult}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if savedCheckpoint}<button class="text-link" onclick={()=>download(savedCheckpoint,'checkpoint.json')}>Save checkpoint ↓</button>{/if}
  {#if totals}<div class="panel"><h2>Demonstration totals</h2>{#each options as option}<p>{option.label}: <strong>{totals.counts[option.id]}</strong></p>{/each}<p>{totals.total} submissions. {totals.warning}</p></div>{/if}
  <h2>Check independently</h2><p>Download <a href="/verify-log.mjs" download>the checker</a> and its <a href="/verify-board.mjs" download>verification module</a> into the same folder as the log and public key. Run with Node 22 or later:</p><pre class="verifier-command">node verify-log.mjs board.json signing-public-key.pem - - {config?.election?.id??'neighborhood-demo-2026'}</pre><p>Add a receipt code (or <code>-</code>) and an earlier checkpoint filename to check inclusion and continuity.</p><p class="fine">Trust depends on an authentic public key and independently retained checkpoints. Signatures cannot stop the operator from showing different histories to different people. The operator can decrypt ballots; the tally is not independently proven. These are fictional volunteer submissions, not an official election.</p></section>
{:else}
  <section class="workspace about"><a class="back" href="/">← Home</a><div class="eyebrow">THEORY ↔ ACTION</div><h1 class="page-title">An argument.<br/><em>And an experiment.</em></h1><p class="intro">What becomes possible when collective decisions are easier to make?</p><p>Voting sits within a wider system: sensing what is happening, deliberating about what matters, deciding together, acting, and learning from the result. A better ballot is one part of that picture.</p><p>Vote Anyway brings an essay and a software experiment into the same place. The essay explores secure internet voting and its democratic possibilities. The prototype gives us something concrete to question, inspect, and improve.</p><div class="roadmap" id="where-we-are"><div class="eyebrow">WHERE WE ARE · OCTOBER 20, 2026</div><article><span class="status">NOW</span><div><h2>Create, share, participate</h2><p>Sign in with attest.monster, create a topic with 2–8 choices, and share its ballot. Participants choose one option and review it before submitting. You can also approve and revoke an agent’s permission to create topics or vote.</p><p>Browser encryption, signed public records, downloadable receipts and an independent record checker are working. Topics and encrypted records persist in PostgreSQL. The site follows your system’s light or dark appearance.</p></div></article><article><span class="status next">LIMITS</span><div><h2>An informal experiment</h2><p>Repeat submissions are allowed: totals count submissions, not unique voters. The operator can decrypt ballots and computes the totals. Record checks establish integrity and receipt inclusion; they do not independently prove the tally or voter eligibility.</p></div></article><article><span class="status next">NEXT</span><div><h2>Electing someone, with clearer rules</h2><p>Design single-winner ranked-choice runoff ballots, with visible transfers and results for each round. Before opening a vote, publish its counting method, closing time, eligibility, repeat-vote policy and tie rules. Ranked ballots and automatic runoffs are not implemented yet.</p><p><a href="/voting-methods.html">Runoffs, vote splitting, and the proposed next experiment →</a></p></div></article><article><span class="status next">EXPLORE</span><div><h2>More ways to decide and verify</h2><p>Approval voting and separate-round runoffs; later, multi-seat representation and revocable delegation. Study reviewed election protocols, independent tally verification, and provisional participation with explicit eligibility decisions.</p></div></article></div><h2>The companion essay: Vote Anyway</h2><p>The core essay makes the persuasive argument. Linked appendices carry the technical detail, citations, previous work, and implementation questions. The development log also holds the evolving outline, earlier drafts, and research notes.</p><a class="primary inline" href="https://github.com/anselm/vote-anyway" target="_blank" rel="noreferrer">Follow the work on GitHub ↗</a> <a class="primary inline" href="/essay.html">Read the essay ↗</a> <a class="primary inline" href="/research.html">Appendices &amp; sources ↗</a></section>
{/if}
</main>
<footer><a class="brand small" href="/">vote anyway.</a><p>An open experiment. A work in progress.</p><span>BUILT IN PUBLIC ↗</span></footer>
